let europeFixturesOpen=false;
function europeStatus(){
 const e=season.europe;if(!e?.enabled)return e?.legacy?'기존 시즌은 그대로 · 다음 시즌부터 출전 자격 적용':'지난 시즌 1부 1~2위가 다음 시즌 출전';
 if(e.champion)return S.club(e.champion).short+' 우승';
 if(e.stage>=6&&!Europe.fixturesFor(season).some(f=>f.home===S.own||f.away===S.own))return '이번 도전 마무리 · 남은 대회 결과 자동 진행';
 return Europe.stageNames[e.stage]+(season.competition==='europe'?' · '+(state?.phase==='full'?'결과 확정 대기':state?.phase==='prep'?'경기 준비':'경기 진행 중'):' · 리그 '+Europe.gateFor(season)+'경기 뒤');
}
function renderEurope(){
 if(view!=='cup')return;const panel=$('europe-panel');if(!panel||typeof Europe==='undefined')return;
 const e=season.europe,active=season.competition==='europe'&&!!state,status=europeStatus();
 const records=season.history.filter(h=>h.europeChampion).map(h=>({year:h.year,champion:h.europeChampion}));if(e?.champion)records.push({year:season.year,champion:e.champion});
 const titleCount=records.filter(r=>r.champion===S.own).length;
 panel.innerHTML='<section class="europe-centre" aria-labelledby="europe-heading"><header class="europe-heading"><div><div class="eyebrow">CHAMPIONS LEAGUE / SEASON '+String(season.year).padStart(2,'0')+'</div><h1 id="europe-heading">유럽의 무대, 우리의 도전.</h1><p>'+escapeText(status)+'</p></div><span class="europe-star" aria-hidden="true">✦</span></header><div class="europe-rules"><span>8팀 · 2개 조 · 상위 2팀 진출</span><span>조별 홈·원정 6경기 → 준결승 → 결승</span><span>조별 무승부 가능 · 토너먼트 무승부는 승부차기</span></div>'+(e?.enabled?'<p class="europe-qualification">'+e.qualification.year+'시즌 1부 '+e.qualification.rank+'위로 출전 · 리그 승점과 별도 집계</p>'+(active?'<button id="europe-match" type="button" class="primary">'+Europe.stageNames[e.stage]+' '+(state.phase==='full'?'결과 확인':'경기로 이동')+'</button>':'')+'<div class="europe-groups">'+[0,1].map(group=>'<section aria-label="챔피언스리그 '+(group?'B':'A')+'조"><h2>'+(group?'B':'A')+'조</h2><div class="table-wrap"><table class="europe-table"><thead><tr><th>순위 / 구단</th><th>경기</th><th>득실</th><th>승점</th></tr></thead><tbody>'+Europe.standings(season,group).map(c=>'<tr class="'+(c.id===S.own?'own-row':'')+'"><th scope="row"><span class="europe-rank">'+c.rank+'</span>'+escapeText(c.short)+'<small>'+(c.id===S.own?'우리 구단':escapeText(c.country))+'</small></th><td>'+c.played+'</td><td>'+(c.gd>0?'+':'')+c.gd+'</td><td><b>'+c.points+'</b></td></tr>').join('')+'</tbody></table></div></section>').join('')+'</div><details class="europe-fixtures" '+(europeFixturesOpen?'open':'')+'><summary>대진과 경기 결과 보기</summary>'+Europe.stageNames.map((name,stage)=>{const fixtures=Europe.fixturesFor(season,stage);return '<section class="europe-stage"><h3>'+name+'<small>리그 '+Europe.gates[stage]+'경기 뒤</small></h3>'+(fixtures.length?fixtures.map(f=>{const r=e.results.find(r=>r.stage===stage&&r.index===f.index);return '<div data-europe-stage="'+stage+'" data-europe-index="'+f.index+'" class="europe-pair '+([f.home,f.away].includes(S.own)?'europe-own-game':'')+'"><span>'+escapeText(S.club(f.home).short)+'</span><b>'+(r?r.goals.join(' : '):'VS')+'</b><span>'+escapeText(S.club(f.away).short)+'</span>'+(r?.penalties?'<small>승부차기 '+r.penalties.join(' : ')+'</small>':'')+'</div>';}).join(''):'<p class="europe-pending">앞 단계 결과가 확정되면 대진이 열립니다.</p>')+'</section>';}).join('')+'</details><p class="finance-note">홈 수입 £26,000 · 원정 £9,000 · 조별 승리 £20,000 / 무승부 £8,000 · 준결승 승리 £60,000 · 우승 £150,000. 별도 주급과 코치 계약 기간은 소모되지 않습니다.</p>':'<div class="europe-empty"><h2>리그에서 유럽으로.</h2><p>5부에서 출발해 매 시즌 승격 경쟁을 통과하고 1부에 올라가세요. 1부에서 1~2위를 기록하면 다음 시즌 챔피언스리그에 도전할 수 있습니다.</p>'+(e?.legacy?'<p>진행 중이던 저장은 현재 일정과 경기 상태를 유지합니다.</p>':'')+'</div>')+'<div class="europe-titles"><strong>챔피언스리그 우승 '+titleCount+'회</strong>'+(records.length?'<p>'+records.map(r=>r.year+'시즌 · '+escapeText(S.club(r.champion).short)+' 우승').join('<br>')+'</p>':'<p>새로운 트로피를 기다립니다.</p>')+'</div></section>';
 if(active)$('europe-match').onclick=()=>setView('match');
 const details=panel.querySelector('.europe-fixtures');if(details)details.ontoggle=()=>{europeFixturesOpen=details.open;};
}
